  Notation RETf mm x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x28 x29 x30 x31 :=
    (MS (mkR ra (Z_to_bv 64 SP) gp tp x5 x6 x7 s0 s1 x10 x11 x12 x13 x14 x15 x16 x17 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
        F (ret_pc ra) fc None mm (seg_rom asegs)).

  (* [comment removed for export] *)
  Lemma fdw_epi : forall (x1 x5 x6 x7 x9 x10 x11 x12 x13 x14 x15 x16 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word) m (FF FLG : Z)
      (j0 : word) csA,
    rw_cells asegs m (Z.shiftr FF 3 + 2147450880) FDSH ->
    rw_cells asegs m FF [C8 j0] -> rw_cells asegs m (FF + 56) [C8 (Z_to_bv 64 FLG)] -> rw_cells asegs m FLG [C1 (Z_to_bv 8 1)] ->
    rw_cells asegs m (SP + -104) FRBf -> rw_cells asegs m SPAf csA -> cells_size csA = 120%nat ->
    stk asegs m lo SPAf -> stk asegs m (SPAf + 120) (SP + -104) -> mem_inv asegs m ->
    ablk FF (FF + 64) -> FF + 64 <= ATOP -> FF mod 64 = 0 -> ablk FLG (FLG + 1) -> FLG + 1 <= ATOP -> (FLG + 1 <= FF \/ FF + 64 <= FLG) ->
    rng RNG FF 64 -> rng RNG (shad FF) 8 -> rng RNG FLG 1 ->
    evtF asegs RNG (fun ms' => exists mp m' (y10 y11 y12 y13 y14 : word),
        ms' = RETf m' x5 x6 x7 x15 y11 y12 y13 y14 x15 x16 (Z_to_bv 64 FF) x28 x29 x30 x31
        /\ munch [(Z.shiftr FF 3 + 2147450880, Z.shiftr FF 3 + 2147450880 + 8); (FF, FF + 8)] m mp /\ wmono asegs m mp /\ mem_inv asegs mp
        /\ munch [(FLG, FLG + 1)] mp m' /\ wmono asegs mp m' /\ mem_inv asegs m'
        /\ stk asegs m' lo SP /\ rw_cells asegs m' FLG [C1 (Z_to_bv 8 0)])
      (MS (mkR x1 (Z_to_bv 64 SPAf) gp tp x5 x6 x7 (Z_to_bv 64 SP) x9 x10 x11 x12 x13 x14 x15 x16 (Z_to_bv 64 FF)
               (Z_to_bv 64 FF) (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880)) x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
